 "content": "from collections import deque


def _shape(points):
    min_r = min(r for r, _ in points)
    min_c = min(c for _, c in points)
    return frozenset((r - min_r, c - min_c) for r, c in points)


def transform(grid):
    h, w = len(grid), len(grid[0])
    frame_color = grid[0][0]
    panel_w = 0
    while panel_w < w and grid[0][panel_w] == frame_color:
        panel_w += 1

    # The horizontal full-color rows delimit the patterned frames.
    dividers = [r for r, row in enumerate(grid)
                if all(row[c] == frame_color for c in range(panel_w))]

    # Catalog the connected colored objects on the right as shape -> color.
    seen = set()
    shape_color = {}
    for r in range(h):
        for c in range(panel_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (nr, nc) not in seen and 0 <= nr < h and panel_w <= nc < w and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            shape_color[_shape(component)] = color

    out = [row[:panel_w] for row in grid]
    for top, bottom in zip(dividers, dividers[1:]):
        holes = [(r, c) for r in range(top + 1, bottom)
                 for c in range(1, panel_w - 1) if grid[r][c] == 0]
        if not holes:
            continue
        color = shape_color.get(_shape(holes))
        if color is not None:
            for r, c in holes:
                out[r][c] = color
    return out
